use std::io;
use std::net::TcpListener;
use std::path::PathBuf;
use std::time::Instant;

use clap::Parser;

use inspire_rs::commons::{
    MSG_HANDSHAKE, MSG_KEYWORD_QUERY, MSG_KEYWORD_RESPONSE, recv_msg, send_msg,
};
use inspire_rs::load_dataset;
use inspire_rs::pir::server::KeywordServer;

#[derive(Parser, Debug)]
#[command(
    version,
    about = "Static keyword PIR server for ML-KEM-768 public keys"
)]
struct Args {
    /// Input dataset file generated by `gen_dataset`.
    #[arg(long)]
    dataset: PathBuf,

    /// Server listen address.
    #[arg(long, default_value = "0.0.0.0:8082")]
    listen: String,

    /// Number of cuckoo buckets / PIR items.
    #[arg(long)]
    buckets: Option<usize>,

    /// First-dimension size override.
    #[arg(long)]
    dim0: Option<usize>,
}

fn log(msg: &str) {
    use std::time::{SystemTime, UNIX_EPOCH};
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    eprintln!("[init {:>6}s] {}", secs % 100000, msg);
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();
    let args = Args::parse();

    log("loading dataset");
    let dataset = load_dataset(&args.dataset)?;
    if dataset.records.is_empty() {
        return Err("dataset must contain at least one record".into());
    }
    log(&format!(
        "loaded {} {} records (public key {} bytes)",
        dataset.records.len(),
        dataset.kem_name,
        dataset.public_key_len
    ));
    log("initializing keyword PIR runtime");
    let keyword_server = KeywordServer::setup_from_dataset(&dataset, args.buckets, args.dim0)?;
    log("keyword PIR runtime ready");
    let public_params = keyword_server.public_params();
    let handshake_json = serde_json::to_vec(&public_params)?;

    println!(
        "serving {} {} public keys on {}",
        dataset.records.len(),
        dataset.kem_name,
        args.listen
    );
    println!(
        "entry size {} bytes, buckets {}, dim0 {}",
        public_params.item_size_bits / 8,
        public_params.num_items,
        public_params.dim0
    );

    let listener = TcpListener::bind(&args.listen)?;
    for incoming in listener.incoming() {
        let mut stream = match incoming {
            Ok(stream) => stream,
            Err(err) => {
                eprintln!("accept error: {err}");
                continue;
            }
        };
        stream.set_nodelay(true).ok();

        if let Err(err) = send_msg(&mut stream, MSG_HANDSHAKE, &handshake_json) {
            eprintln!("handshake send failed: {err}");
            continue;
        }

        loop {
            let start = Instant::now();
            let (msg_type, query_bytes) = match recv_msg(&mut stream) {
                Ok(message) => message,
                Err(err) if err.kind() == io::ErrorKind::UnexpectedEof => break,
                Err(err) => {
                    eprintln!("client error: {err}");
                    break;
                }
            };

            if msg_type != MSG_KEYWORD_QUERY {
                eprintln!("client error: unexpected message type {msg_type}");
                break;
            }

            let response_bytes = keyword_server.respond_to_serialized_query(query_bytes);
            if let Err(err) = send_msg(&mut stream, MSG_KEYWORD_RESPONSE, &response_bytes) {
                eprintln!("client error: {err}");
                break;
            }
            println!(
                "query answered in {:.1}ms",
                start.elapsed().as_secs_f64() * 1000.0
            );
        }
    }

    Ok(())
}
